        body: "ಸ್ಮಾಲ್-ಕ್ಯಾಪ್ ಫಂಡ್ ಮತ್ತು liquid ಫಂಡ್ ಹೋಲಿಸಲಾಗದವು, ಹಾಗಾಗಿ ಇಲ್ಲಿನ ಪ್ರತಿ ಸಾಪೇಕ್ಷ ಸಂಖ್ಯೆಯೂ ಫಂಡ್ ಅನ್ನು ಅದರದ್ದೇ SEBI ಸಬ್-ಕ್ಯಾಟಗರಿಯ ಫಂಡ್‌ಗಳ ಜೊತೆ ಮಾತ್ರ ಹೋಲಿಸುತ್ತದೆ - Flexi Cap ಜೊತೆ Flexi Cap, Small Cap ಜೊತೆ Small Cap. ಆ ಗುಂಪೇ ಫಂಡ್‌ನ ಪೀರ್‌ಗಳು. ಈ ಸೈಟ್‌ನಲ್ಲಿ 'ಒಂದೇ ರೀತಿಯ ಫಂಡ್‌ಗಳು' ಎಂದು ಕಂಡರೆ ಅದರ ಅರ್ಥ ಇದೇ. ಪೀರ್ ಸರಾಸರಿ ಲೆಕ್ಕದಿಂದ ಫಂಡ್ ಅನ್ನೇ ಹೊರಗಿಡುತ್ತದೆ, ಹಾಗಾಗಿ ದೊಡ್ಡ ಫಂಡ್ ಅನ್ನು ಭಾಗಶಃ ಅದರ ಎದುರೇ ಅಳೆಯುವುದಿಲ್ಲ. ನ್ಯಾಯಯುತ ಸರಾಸರಿಗೆ ಸಬ್-ಕ್ಯಾಟಗರಿಯಲ್ಲಿ ತುಂಬಾ ಕಡಿಮೆ ಫಂಡ್‌ಗಳಿದ್ದರೆ, ಕೆಲವೇ ಫಂಡ್‌ಗಳ ಮೇಲೆ ಲೆಕ್ಕ ಹಾಕುವ ಬದಲು ಹೋಲಿಕೆಯನ್ನು ಖಾಲಿ ಬಿಡಲಾಗುತ್ತದೆ.",
