        body: "ಫಂಡ್ ತನ್ನ ಇಂಡೆಕ್ಸ್ ಅನ್ನು ಮೀರಿಸಿದಾಗ, ಅದು ಕೌಶಲವೂ ಆಗಿರಬಹುದು ಅದೃಷ್ಟವೂ ಆಗಿರಬಹುದು. ಕೇವಲ ಅದೃಷ್ಟ ಅಷ್ಟು ಒಳ್ಳೆಯ ಫಲಿತಾಂಶವನ್ನು ಎಷ್ಟು ಸುಲಭವಾಗಿ ತರಬಹುದಿತ್ತು ಎಂದು p-value ಅಂದಾಜಿಸುತ್ತದೆ. ಕಡಿಮೆ p-value ಎಂದರೆ ಅದೃಷ್ಟ ದುರ್ಬಲ ವಿವರಣೆ. ಸಮಸ್ಯೆ ಪ್ರಮಾಣದ್ದು: ಹತ್ತಾರು ಸಾವಿರ ಫಂಡ್‌ಗಳನ್ನು ಸ್ಕ್ರೀನ್ ಮಾಡಿದರೆ ಸುಮಾರು 5% ಫಂಡ್‌ಗಳು ಯಾವುದೇ ಕೌಶಲವಿಲ್ಲದೆ ಕೇವಲ ಆಕಸ್ಮಿಕವಾಗಿ ಸಾಮಾನ್ಯ ಮಿತಿಯನ್ನು ದಾಟುತ್ತವೆ - ಇಲ್ಲಿ ಅದು ಸಾವಿರಕ್ಕೂ ಹೆಚ್ಚು ಫಂಡ್‌ಗಳು. ಹಾಗಾಗಿ ಸ್ಕ್ರೀನಿಂಗ್‌ನಿಂದ ಸಿಕ್ಕ ಒಂದು ಆಕರ್ಷಕ p-value, ನೀವು ಈಗಾಗಲೇ ಪರಿಶೀಲಿಸುತ್ತಿದ್ದ ಫಂಡ್‌ಗೆ ಸಿಕ್ಕ ಅದೇ p-value ಗಿಂತ ಬಹಳ ದುರ್ಬಲ ಪುರಾವೆ. ನಿರೀಕ್ಷಿತ false-positive ಎಣಿಕೆಯನ್ನು ವಿಧಾನ ಪುಟ ತಿಳಿಸುತ್ತದೆ.",
